// Shape of the static files generated by `npm run data` into public/data.

export type Lang = 'pt' | 'en';
export type LocalizedText = Record<Lang, string>;
export type LocalizedList = Record<Lang, string[]>;

export type Continent =
  'africa' | 'antarctica' | 'asia' | 'europe' | 'north-america' | 'oceania' | 'south-america';

export interface Capital {
  wikidata: string;
  name: LocalizedText;
  aliases: LocalizedList;
}

/** One of the 195 countries (countries.json). `id` is the ISO 3166-1 alpha-3 code. */
export interface Country {
  id: string;
  iso2: string;
  wikidata: string;
  name: LocalizedText;
  aliases: LocalizedList;
  capitals: Capital[];
  continent: Continent;
  areaKm2: number;
  /** Who claims this place, for the dispute note in the info card. */
  claimedBy: Claimant[];
  /** Path relative to public/data. */
  flag: string;
  /** [longitude, latitude] for a label or a clickable spot (tiny places). */
  labelPoint: LonLat;
}

export type LonLat = [number, number];

/** `country` is set when the claimant is one of the 195; otherwise only the name is known. */
export interface Claimant {
  country: string | null;
  name: LocalizedText;
}

/** A place that is not one of the 195 countries (territories.json). */
export interface Territory extends Omit<Country, 'iso2'> {
  iso2: string | null;
  /** Country it counts as when territories are turned off; null = never a target then. */
  administeredBy: string | null;
  /** Explains the status of places without an administering country. */
  statusNote: LocalizedText | null;
}

/** Federative unit of Brazil (states.json). `id` is the abbreviation, e.g. "SP". */
export interface BrazilState {
  id: string;
  ibgeCode: number;
  wikidata: string;
  name: LocalizedText;
  aliases: LocalizedList;
  capitals: Capital[];
  region: string;
  areaKm2: number;
  flag: string;
  labelPoint: LonLat;
}

/** Anything the player can be asked about, and the info card can describe. */
export type Place = Country | Territory | BrazilState;

/** Which map a game is played on. */
export type Layer = 'world' | 'brazil';

/** Region of Brazil (regions-br.json). `id` is the IBGE abbreviation, e.g. "SE". */
export interface BrazilRegion {
  id: string;
  name: LocalizedText;
}

/** Properties of each feature in world.topo.json (object "units"). */
export interface WorldUnitProperties {
  id: string;
  /** Country it belongs to when territories are off (null = never a target then). */
  country: string | null;
  /** Its own target id when territories are on (null = part of `country`). */
  territory: string | null;
}
